  test('ignores leading and trailing blank lines', () => {
    expect(parseCsv('\nid,name\n1,Ada\n')).toEqual([{ id: '1', name: 'Ada' }]);
  });

  test('returns no rows when only a header is present', () => {
    expect(parseCsv('id,name')).toEqual([]);
  });
});

