    {
      displayName: 'e2e',
      rootDir: __dirname,
      testEnvironment: 'node',
      testMatch: ['<rootDir>/e2e/**/*.test.ts'],
      transform: tsTransform,
      // Child-process cases are slower than in-process ones, but still bounded.
      testTimeout: 30_000,
    },
  ],
};

